def render_timeline(payload):
    if not isinstance(payload, dict):
        return "invalid"

    # Check for "tol" and "gap" parameters
    tol = payload.get("tol")
    gap = payload.get("gap")

    # Validate "tol" if present
    if "tol" in payload:
        if not isinstance(tol, int) or tol < 0:
            return "invalid"

    # Validate "gap" if present
    if "gap" in payload:
        if not isinstance(gap, int) or gap < 0:
            return "invalid"

    # Extract samples and cues
    if "samples" not in payload or "cues" not in payload:
        return "invalid"

    samples = payload["samples"]
    cues = payload["cues"]

    # Handle "tol" in samples
    if "tol" in payload:
        samples = {"samples": samples, "tol": tol}

    # Handle "gap" in cues
    if "gap" in payload:
        cues = {"cues": cues, "gap": gap}

    # Compact the samples
    runs = compact_cue(samples)
    if runs == "invalid":
        return "invalid"

    # Schedule the cues
    plan = schedule_cues(cues)
    if plan == "invalid":
        return "invalid"

    # Check for "detail" parameter
    detail = payload.get("detail")
    if detail is not None:
        if not isinstance(detail, bool):
            return "invalid"
        if detail:
            # Generate the "order" list
            # Extract and sort cues by requested start time, preserving input order for ties
            cue_list = []
            for item in cues:
                if not isinstance(item, dict):
                    return "invalid"

                if "id" not in item or "at" not in item or "dur" not in item:
                    return "invalid"

                cue_id = item["id"]
                at = item["at"]
                dur = item["dur"]

                # Check if at and dur are integers and meet the requirements
                if not isinstance(at, int) or at < 0:
                    return "invalid"
                if not isinstance(dur, int) or dur < 1:
                    return "invalid"

                cue_list.append({"id": cue_id, "at": at, "dur": dur})

            # Sort cues by requested start time, preserving input order for ties
            cue_list.sort(key=lambda x: x["at"])

            order = [cue["id"] for cue in cue_list]

            # Return the detailed result
            return {
                "version": 1,
                "runs": runs,
                "plan": plan,
                "order": order
            }

    # Return the default list result
    return [runs, plan]
